    "id": "Semester 3-DBMS-Module 3-11_Self_Learning_Triggers",
    "relPath": "Semester 3/DBMS/Module 3/11_Self_Learning_Triggers.md",
    "pdfPath": "PDF_Notes/Semester 3/DBMS/Module 3/11_Self_Learning_Triggers.pdf",
