    "id": "Semester 3-MPCA-Module 1-4_Architecture_8086_Family",
    "relPath": "Semester 3/MPCA/Module 1/4_Architecture_8086_Family.md",
    "pdfPath": "PDF_Notes/Semester 3/MPCA/Module 1/4_Architecture_8086_Family.pdf",
