    "id": "Semester 3-MPCA-Module 2-5_Microinstruction_Sequencing_Execution",
    "relPath": "Semester 3/MPCA/Module 2/5_Microinstruction_Sequencing_Execution.md",
    "pdfPath": "PDF_Notes/Semester 3/MPCA/Module 2/5_Microinstruction_Sequencing_Execution.pdf",
